import{_ as t,o,c as a,a3 as s}from"./chunks/framework.BTQ4eCVb.js";const g=JSON.parse('{"title":"Expenses Module","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Expenses Module | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/user-guide/expenses-overview"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Expenses Module | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/user-guide/expenses-overview"}]]},"headers":[],"relativePath":"user-guide/expenses-overview.md","filePath":"user-guide/expenses-overview.md","lastUpdated":1788459257000}'),n={name:"user-guide/expenses-overview.md"};function r(d,e,i,c,l,p){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="expenses-module" tabindex="-1">Expenses Module <a class="header-anchor" href="#expenses-module" aria-label="Permalink to &quot;Expenses Module&quot;">​</a></h1><p>Phase 4 Purchasing module (Milestone 3, final) on the frozen platform. A simplified single-amount expense record — number, category, amount, tax, status workflow, assignment, notes, and an activity timeline — with <strong>soft, optional</strong> links to Vendors and Purchase Orders. Unlike Purchase Orders (hard-depends on Vendors), Expenses is <strong>standalone</strong>: it installs with no module dependencies, and works fully on its own.</p><h2 id="guides" tabindex="-1">Guides <a class="header-anchor" href="#guides" aria-label="Permalink to &quot;Guides&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Audience</th><th>Document</th></tr></thead><tbody><tr><td>Operators / workspace users</td><td><a href="/user-guide/expenses">expenses.md</a></td></tr><tr><td>Engineers</td><td><a href="/developer-guide/expenses">expenses-developer.md</a></td></tr><tr><td>Production / ops</td><td><a href="/deployment/expenses">expenses-production.md</a></td></tr><tr><td>Module Development Standard</td><td><a href="/developer-guide/module-development">module-development.md</a></td></tr><tr><td>Reference blueprint</td><td><a href="/user-guide/purchase-orders-overview">purchase-orders-overview.md</a></td></tr><tr><td>Tenant API</td><td><a href="/api/tenant-v1-expenses">../api/tenant-v1-expenses.md</a></td></tr></tbody></table><h2 id="capabilities" tabindex="-1">Capabilities <a class="header-anchor" href="#capabilities" aria-label="Permalink to &quot;Capabilities&quot;">​</a></h2><ul><li>Header only, no line items: number (<code>EXP-</code> prefix, configurable), title, tenant-managed category, amount, tax amount, currency, expense date, status, notes</li><li>Optional <code>vendor_id</code> and <code>purchase_order_id</code> — soft links, only validated (and only pickable in the UI) when the corresponding module is entitled on the workspace</li><li>Status workflow: <code>draft → submitted → approved | rejected</code>, <code>approved → paid</code>, <code>draft | submitted → cancelled</code></li><li>Draft-only field edits — after <strong>Submit</strong>, only status actions and assignment remain available</li><li>Assignment (<code>created_by</code> / <code>assigned_to</code>) with assignee scoping via <code>expenses.assign</code></li><li>Notes (comments) + activity timeline</li><li>Table view with search, status filter, category filter, assignee filter, and <strong>My Expenses</strong> toggle; <strong>Manage categories</strong> dialog (same <code>expenses.*</code> permissions as Product Categories)</li><li>KPIs via <code>GET /expenses/stats</code> (total, mine, draft, submitted, approved, rejected, paid, cancelled, approved value, paid value)</li><li>Dashboard widget <code>pending_expenses</code> (module + <code>expenses.view</code>; submitted awaiting approval)</li><li>Trash filtering plus <strong>Restore</strong> and <strong>Delete permanently</strong></li><li><strong>Receipt attachments</strong> (optional <code>receipt</code> file on create/draft edit; jpg/png/pdf and common types; counts toward <a href="/user-guide/storage-overview">Storage</a> quota; download from expense record)</li><li>Module licensing (<code>module:expenses</code>) + Spatie permissions — <strong>free Marketplace opt-in</strong>, no hard dependencies</li><li><strong>Soft convert</strong>: a <code>purchase-orders.convert</code> action creates a draft Expense from a sent/partially received/received Purchase Order (one-way, one-time) — see <a href="/user-guide/purchase-orders#convert-to-expense">Purchase Orders — User Guide</a></li><li>Audit + activity logging</li></ul><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><p><code>expenses.view</code> · <code>create</code> · <code>update</code> · <code>delete</code> · <code>restore</code> · <code>force.delete</code> · <code>assign</code> · <code>submit</code> · <code>approve</code> · <code>reject</code> · <code>pay</code> · <code>cancel</code></p><p>Enable Expenses from Marketplace (free) — it has no hard dependencies, so it can be installed on its own, before or after Vendors / Purchase Orders. Catalog: slug <code>expenses</code>, category <code>purchasing</code> (Purchasing), <code>is_default_included = false</code>, <code>is_billable = false</code>, <code>sort_order = 30</code>, version <strong>1.3.0</strong>.</p><h2 id="why-standalone-soft-dependencies" tabindex="-1">Why standalone (soft dependencies) <a class="header-anchor" href="#why-standalone-soft-dependencies" aria-label="Permalink to &quot;Why standalone (soft dependencies)&quot;">​</a></h2><p>Purchase Orders hard-depends on Vendors because every purchase order <strong>must</strong> reference a vendor. Expenses is different — most day-to-day spend (a taxi ride, a software subscription) has no vendor or purchase order behind it, so both links are optional and only appear once the related module is installed. This keeps Expenses usable as a lightweight, install-anywhere module rather than forcing the full Purchasing stack.</p><h2 id="explicitly-deferred" tabindex="-1">Explicitly deferred <a class="header-anchor" href="#explicitly-deferred" aria-label="Permalink to &quot;Explicitly deferred&quot;">​</a></h2><ul><li>Reimbursement workflows and payout tracking beyond the <code>paid</code> status flag</li><li>Expense unpay / reverse the paid Accounting journal from the expense record</li><li>Multi-line expenses (itemized receipts) — this MVP is single-amount only</li></ul><blockquote><p><strong>Accounting soft integration (shipped):</strong> when Accounting is installed, <strong>Mark as paid</strong> requires a cash/bank <strong>Paid from</strong> account and posts a journal. See <a href="/user-guide/accounting">Accounting</a>.</p></blockquote>',14)])])}const h=t(n,[["render",r]]);export{g as __pageData,h as default};
